import type { Paise } from './business.ts';

export const SQFT_PER_SQM = 10.7639;
export const FT_PER_M = 3.28084;

// ---------------------------------------------------------------------------
// Rounding
// ---------------------------------------------------------------------------

/**
 * Rounds half away from zero to `dp` decimal places. The `toPrecision(15)`
 * step removes binary representation noise first, so 1.005 rounds to 1.01
 * (as a person would) rather than 1.00.
 */
export function roundHalfAway(value: number, dp = 0): number {
  if (!Number.isFinite(value)) throw new Error(`Cannot round a non-finite number (${value})`);
  const f = 10 ** dp;
  const a = Number((Math.abs(value) * f).toPrecision(15));
  const r = Math.round(a) / f;
  return value < 0 ? (r === 0 ? 0 : -r) : r;
}

/** Integer division of BigInts, rounding half away from zero. */
export function divRoundBig(n: bigint, d: bigint): bigint {
  if (d === 0n) throw new Error('Division by zero');
  const neg = (n < 0n) !== (d < 0n);
  const an = n < 0n ? -n : n;
  const ad = d < 0n ? -d : d;
  let q = an / ad;
  if ((an % ad) * 2n >= ad) q += 1n;
  return neg ? -q : q;
}

/**
 * A percentage as an exact integer in millionths of the whole
 * (18% → 180_000, 12.5% → 125_000). Percentages carry at most 4 dp.
 */
export function pctToMicro(pct: number): bigint {
  return BigInt(roundHalfAway(pct * 10_000));
}

/** Exact `amount × pct / 100`, rounded once, half away from zero. */
export function pctOf(amount: Paise, pct: number): Paise {
  assertPaise(amount, 'amount');
  return Number(divRoundBig(BigInt(amount) * pctToMicro(pct), 1_000_000n));
}

export function assertPaise(p: number, label = 'amount'): void {
  if (!Number.isSafeInteger(p)) throw new Error(`${label} must be an integer number of paise, got ${p}`);
}

// ---------------------------------------------------------------------------
// Rupees ⇄ paise
// ---------------------------------------------------------------------------

/** Paise → rupees, for display maths only. Never feed the result back into a total. */
export function rupees(p: Paise): number {
  return p / 100;
}

/** Rupees → paise, rounded half away from zero (₹10.005 → 1001 paise). */
export function paise(r: number): Paise {
  return roundHalfAway(r * 100);
}

// ---------------------------------------------------------------------------
// Formatting
// ---------------------------------------------------------------------------

/** "1234567" → "12,34,567" (last three digits, then groups of two). */
function groupIndian(digits: string): string {
  if (digits.length <= 3) return digits;
  const last3 = digits.slice(-3);
  let rest = digits.slice(0, -3);
  const groups: string[] = [];
  while (rest.length > 2) {
    groups.unshift(rest.slice(-2));
    rest = rest.slice(0, -2);
  }
  if (rest) groups.unshift(rest);
  return `${groups.join(',')},${last3}`;
}

export interface FormatINROptions {
  /** Show paise ("₹12,34,567.50"). Default true. When false the amount is rounded to the rupee. */
  paise?: boolean;
  /** Prefix "₹". Default true. */
  symbol?: boolean;
}

/** Indian digit grouping: 123456750 paise → "₹12,34,567.50". Negative → "-₹1,234.00". */
export function formatINR(p: Paise, opts: FormatINROptions = {}): string {
  assertPaise(p);
  const showPaise = opts.paise ?? true;
  const sym = opts.symbol ?? true ? '₹' : '';
  const neg = p < 0;
  let abs = Math.abs(p);
  let body: string;
  if (showPaise) {
    const r = Math.floor(abs / 100);
    const ps = abs % 100;
    body = `${groupIndian(String(r))}.${String(ps).padStart(2, '0')}`;
  } else {
    abs = roundHalfAway(abs / 100);
    body = groupIndian(String(abs));
  }
  return `${neg && body.replace(/[0.,]/g, '') !== '' ? '-' : ''}${sym}${body}`;
}

// ---------------------------------------------------------------------------
// Amount in words (Indian system: thousand, lakh, crore)
// ---------------------------------------------------------------------------

const ONES = [
  'Zero', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten',
  'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen',
];
const TENS = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

function below100(n: number): string {
  if (n < 20) return ONES[n];
  const t = TENS[Math.floor(n / 10)];
  return n % 10 ? `${t}-${ONES[n % 10]}` : t;
}

function below1000(n: number): string {
  const h = Math.floor(n / 100);
  const r = n % 100;
  const parts: string[] = [];
  if (h) parts.push(`${ONES[h]} Hundred`);
  if (r) parts.push(below100(r));
  return parts.join(' ');
}

/** Whole number in Indian words; 0 → "Zero". Crores recurse: 1,50,000 crore → "One Lakh Fifty Thousand Crore". */
export function numberInWordsIndian(n: number): string {
  if (!Number.isSafeInteger(n) || n < 0) throw new Error(`Expected a non-negative integer, got ${n}`);
  if (n === 0) return 'Zero';
  const crore = Math.floor(n / 10_000_000);
  const lakh = Math.floor((n % 10_000_000) / 100_000);
  const thousand = Math.floor((n % 100_000) / 1000);
  const rest = n % 1000;
  const parts: string[] = [];
  if (crore) parts.push(`${numberInWordsIndian(crore)} Crore`);
  if (lakh) parts.push(`${below100(lakh)} Lakh`);
  if (thousand) parts.push(`${below100(thousand)} Thousand`);
  if (rest) parts.push(below1000(rest));
  return parts.join(' ');
}

/**
 * 123456750 → "Rupees Twelve Lakh Thirty-Four Thousand Five Hundred Sixty-Seven and Fifty Paise Only".
 * 0 → "Rupees Zero Only"; 1 → "Rupees Zero and One Paise Only"; negative amounts get "Minus ".
 */
export function amountInWords(p: Paise): string {
  assertPaise(p);
  const neg = p < 0;
  const abs = Math.abs(p);
  const r = Math.floor(abs / 100);
  const ps = abs % 100;
  let s = `Rupees ${numberInWordsIndian(r)}`;
  if (ps) s += ` and ${below100(ps)} Paise`;
  s += ' Only';
  return neg ? `Minus ${s}` : s;
}

// ---------------------------------------------------------------------------
// Trade units (no rounding here — rounding belongs to the display quantity)
// ---------------------------------------------------------------------------

export const toSqft = (m2: number): number => m2 * SQFT_PER_SQM;
export const fromSqft = (sqft: number): number => sqft / SQFT_PER_SQM;
export const toRft = (m: number): number => m * FT_PER_M;
export const fromRft = (ft: number): number => ft / FT_PER_M;
